# owner: platform
"""Seating rows built from a list of students."""

from typing import List

from rosterkit.errors import ProjectError
from rosterkit.models import Student


def _validate(students: List[Student], seats: int) -> None:
    if seats < 1:
        raise ProjectError("seats per row must be positive")
    if not students:
        raise ProjectError("no students to seat")


def _sort_key(student: Student) -> tuple:
    return (student.last_name.lower(), student.first_name.lower())


def _label(student: Student) -> str:
    return f"{student.last_name}, {student.first_name}"


def _chunk(names: List[str], seats: int) -> List[str]:
    lines = []
    for start in range(0, len(names), seats):
        part = " | ".join(names[start:start + seats])
        lines.append(f"Row {start // seats + 1}: {part}")
    return lines


# ---
def seating_rows(
    students: List[Student],
    seats: int
) -> List[str]:
    _validate(students, seats)
    ordered = sorted(students, key=_sort_key)
    names = [_label(stud) for stud in ordered]
    return _chunk(names, seats)

