# owner: platform
import unittest

from rosterkit.seating import seating_rows
from rosterkit.models import Student
from rosterkit.errors import ProjectError


# ---
def build_student(last: str, first: str) -> Student:
    return Student("1", last, first, "A")


class SeatingRowsTest(unittest.TestCase):
    # ---
    def test_sorts_and_splits_rows(self):
        crowd = [
            build_student("Halloway", "Juno"),
            build_student("Dunmere", "Piet"),
            build_student("Aldous", "Mara")
        ]
        result = seating_rows(crowd, 2)
        self.assertEqual(result, [
            "Row 1: Aldous, Mara | Dunmere, Piet",
            "Row 2: Halloway, Juno"
        ])

    # ---
    def test_first_name_breaks_ties(self):
        crowd = [
            build_student("Lund", "Zed"),
            build_student("Lund", "Abel")
        ]
        result = seating_rows(crowd, 5)
        self.assertEqual(
            result, ["Row 1: Lund, Abel | Lund, Zed"]
        )

    # ---
    def test_bad_seat_counts_raise(self):
        crowd = [build_student("Lund", "Zed")]
        for seats in (0, -3):
            with self.assertRaises(ProjectError):
                seating_rows(crowd, seats)

    # ---
    def test_no_students_raises(self):
        with self.assertRaises(ProjectError):
            seating_rows([], 3)


if __name__ == "__main__":
    unittest.main()
